      sortBy?: string;
      /** Maps to API query `sort_dir` (`asc` / `desc`). */
      sortOrder?: 'ASC' | 'DESC' | 'asc' | 'desc' | string;
      /** Same as `sortBy` (sent as `sort` on the wire). */
      sort?: string;
      sort_column?: string;
